// ============================================================
// EXPORTED FUNCTIONS
// ============================================================

export function t(key: string, lang: Language): string {
  return translations[key]?.[lang] || translations[key]?.en || key.replace(/_/g, ' ');
}

export function tMonster(id: string, lang: Language): string {
  return monsterNames[id]?.[lang] || monsterNames[id]?.en || id.replace(/_/g, ' ');
}

export function tMove(id: string, lang: Language): string {
  return moveNames[id]?.[lang] || moveNames[id]?.en || id.replace(/_/g, ' ');
}

export function tAbility(name: string, lang: Language): string {
  return abilityNames[name]?.[lang] || abilityNames[name]?.en || name.replace(/_/g, ' ');
}

export function tAbilityDesc(name: string, lang: Language): string {
  return abilityDescs[name]?.[lang] || abilityDescs[name]?.en || name.replace(/_/g, ' ');
}

export function tItem(id: string, lang: Language): string {
  return itemNames[id]?.[lang] || itemNames[id]?.en || id.replace(/_/g, ' ');
}

export function tItemDesc(id: string, lang: Language): string {
  return itemDescs[id]?.[lang] || itemDescs[id]?.en || id.replace(/_/g, ' ');
}

export function tType(type: string, lang: Language): string {
  return typeNames[type]?.[lang] || typeNames[type]?.en || type.replace(/_/g, ' ');
}

export function tStatus(status: string, lang: Language): string {
  return statusNames[status]?.[lang] || statusNames[status]?.en || status.replace(/_/g, ' ');
}
